#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

class Solution {
public:
    int minimumCost(std::string sentence, int k) {
        std::stringstream ss(sentence);
        std::string w;
        std::vector<int> lens;
        while (ss >> w) {
            lens.push_back(w.size());
        }

        int n = lens.size();
        std::vector<int> memo(n + 1, -1);

        auto dfs = [&](auto& self, int i) -> int {
            if (i == n) return 0;
            if (memo[i] != -1) return memo[i];

            int res = 1e9;
            int currLen = -1;
            for (int j = i; j < n; ++j) {
                currLen += lens[j] + 1;
                if (currLen > k) break;
                int rowCost = (j == n - 1) ? 0 : (k - currLen) * (k - currLen);
                res = std::min(res, rowCost + self(self, j + 1));
            }
            return memo[i] = res;
        };

        return dfs(dfs, 0);
    }
};

import java.util.Arrays;

class Solution {
    public int minimumCost(String sentence, int k) {
        String[] words = sentence.split(" ");
        int n = words.length;
        int[] lens = new int[n];
        for (int i = 0; i < n; i++) lens[i] = words[i].length();

        int[] memo = new int[n + 1];
        Arrays.fill(memo, -1);
        return dfs(0, lens, k, memo);
    }

    private int dfs(int i, int[] lens, int k, int[] memo) {
        int n = lens.length;
        if (i == n) return 0;
        if (memo[i] != -1) return memo[i];

        int res = Integer.MAX_VALUE;
        int currLen = -1;
        for (int j = i; j < n; j++) {
            currLen += lens[j] + 1;
            if (currLen > k) break;
            int rowCost = (j == n - 1) ? 0 : (k - currLen) * (k - currLen);
            int nextCost = dfs(j + 1, lens, k, memo);
            if (nextCost != Integer.MAX_VALUE) {
                res = Math.min(res, rowCost + nextCost);
            }
        }
        return memo[i] = res;
    }
}

